corrected_code:
users_router = APIRouter(prefix="/users", tags=["users"])

@users_router.patch("/{id}/custom-profile", response_model=UserRead)
async def update_custom_profile(
    id: uuid.UUID,
    profile_update: CustomProfileUpdateSchema,
    user_manager: BaseUserManager = Depends(get_user_manager),
    current_user: User = Depends(current_active_user)
):
    if current_user.id != id and not current_user.is_superuser:
        raise HTTPException(status_code=403, detail="Forbidden: cannot update other users' profile")

    user = await user_manager.get(id)
    if not user:
        raise HTTPException(status_code=404, detail="User not found")

    update_data = profile_update.dict(exclude_unset=True)
    return await user_manager.update(user, update_data, safe=False)
